# Initially generated by GitHub Copilot.
"""Render the json-snippet slide for the what-is-mam deck."""

import pathlib
from typing import Callable

from bidi.algorithm import get_display
from PIL import Image, ImageDraw, ImageFont
from pygments import lex
from pygments.lexers import JsonLexer
from pygments.token import Token

_JSON_PATH = pathlib.Path("misc/what-is-mam/img-sources/json-snippet.json")
_FONT_DIR = pathlib.Path("C:/Windows/Fonts")
_FONT_SIZE = 44

# VS Code Dark+ color scheme
_COLOR_KEY = (156, 220, 254)  # light blue — JSON keys
_COLOR_STRING = (206, 145, 120)  # warm orange — string values
_COLOR_NUMBER = (181, 206, 168)  # light green — numbers
_COLOR_KEYWORD = (86, 156, 214)  # blue — true/false/null
_COLOR_PUNCT = (212, 212, 212)  # light gray — punctuation & whitespace


def _token_color(ttype):
    if ttype is Token.Name.Tag:
        return _COLOR_KEY
    if ttype in Token.Literal.String:
        return _COLOR_STRING
    if ttype in Token.Literal.Number:
        return _COLOR_NUMBER
    if ttype in Token.Keyword:
        return _COLOR_KEYWORD
    return _COLOR_PUNCT


def _has_hebrew(text):
    return any("\u0590" <= ch <= "\u05ff" for ch in text)


def _build_lines(json_text):
    """Tokenize JSON and return list of lines, each a list of (text, color)."""
    lines = []
    current_line = []
    for ttype, value in lex(json_text, JsonLexer()):
        if ttype in Token.Text:
            # Split on embedded newlines, flushing a new line on each
            parts = value.split("\n")
            for i, part in enumerate(parts):
                if part:
                    current_line.append((part, _COLOR_PUNCT))
                if i < len(parts) - 1:
                    lines.append(current_line)
                    current_line = []
        else:
            color = _token_color(ttype)
            text = get_display(value) if _has_hebrew(value) else value
            current_line.append((text, color))
    if current_line:
        lines.append(current_line)
    return lines


def render_json_snippet(
    images_dir: pathlib.Path,
    img_factory: Callable[[], Image.Image],
) -> None:
    """Render slide-json-snippet.png with syntax-colored JSON."""
    json_text = _JSON_PATH.read_text(encoding="utf-8")
    lines = _build_lines(json_text)

    # Consolas for pure-ASCII tokens; Arial for Hebrew-containing tokens
    font_ascii = ImageFont.truetype(str(_FONT_DIR / "consola.ttf"), size=_FONT_SIZE)
    font_heb = ImageFont.truetype(str(_FONT_DIR / "arial.ttf"), size=_FONT_SIZE)

    def _font_for(text):
        return font_heb if _has_hebrew(text) else font_ascii

    img = img_factory()
    W, H = img.size
    draw = ImageDraw.Draw(img)

    # Determine line height from representative glyphs across both fonts
    bb_ascii = draw.textbbox((0, 0), "Ag", font=font_ascii)
    bb_heb = draw.textbbox(
        (0, 0), "\N{HEBREW LETTER ALEF}\N{HEBREW POINT QAMATS}", font=font_heb
    )
    raw_h = max(bb_ascii[3] - bb_ascii[1], bb_heb[3] - bb_heb[1])
    line_height = int(raw_h * 1.8)

    # Pass 1: measure each line width so we can center the block
    line_widths = []
    for line_segs in lines:
        x = 0
        for text, _color in line_segs:
            if text:
                font = _font_for(text)
                bb = draw.textbbox((0, 0), text, font=font)
                x += bb[2] - bb[0]
        line_widths.append(x)

    max_width = max(line_widths) if line_widths else 0
    x0 = max(60, (W - max_width) // 2)
    total_height = line_height * len(lines)
    y0 = (H - total_height) // 2

    # Pass 2: draw
    y = y0
    for line_segs in lines:
        x = x0
        for text, color in line_segs:
            if text:
                font = _font_for(text)
                bb = draw.textbbox((x, y), text, font=font)
                draw.text((x, y), text, font=font, fill=color)
                x += bb[2] - bb[0]
        y += line_height

    dest = images_dir / "slide-json-snippet.png"
    img.save(dest)
    print(f"Saved {dest} {img.size}")
